  fun writeRuntimeEvent(arena: MemScope, value: RuntimeEvent): CPointer<mln_runtime_event> {
    val result = arena.alloc<mln_runtime_event>().ptr
    result.reinterpret<ByteVar>().let { bytes ->
      repeat(sizeOf<mln_runtime_event>().toInt()) { bytes[it] = 0 }
    }
    result.pointed.type = value.type.rawValue
    result.pointed.source_type = value.sourceType.rawValue
    result.pointed.source = value.source
    result.pointed.code = value.code
    when (val variant = value.payload) {
      is RuntimeEventPayload.RenderFrame -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_RENDER_FRAME
        GeneratedValues.writeRuntimeEventRenderFrame(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.payload.render_frame.ptr)
      }
      is RuntimeEventPayload.RenderMap -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_RENDER_MAP
        GeneratedValues.writeRuntimeEventRenderMap(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.payload.render_map.ptr)
      }
      is RuntimeEventPayload.TileAction -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_TILE_ACTION
        GeneratedValues.writeRuntimeEventTileAction(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.payload.tile_action.ptr)
      }
      is RuntimeEventPayload.OfflineRegionStatus -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_STATUS
        GeneratedValues.writeRuntimeEventOfflineRegionStatus(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.payload.offline_region_status.ptr)
      }
      is RuntimeEventPayload.OfflineRegionResponseError -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_RESPONSE_ERROR
        GeneratedValues.writeRuntimeEventOfflineRegionResponseError(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.payload.offline_region_response_error.ptr)
      }
      is RuntimeEventPayload.OfflineRegionTileCountLimit -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_TILE_COUNT_LIMIT
        GeneratedValues.writeRuntimeEventOfflineRegionTileCountLimit(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.payload.offline_region_tile_count_limit.ptr)
      }
      is RuntimeEventPayload.CameraTransitionFinished -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_CAMERA_TRANSITION_FINISHED
        GeneratedValues.writeRuntimeEventCameraTransitionFinished(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.payload.camera_transition_finished.ptr)
      }
      RuntimeEventPayload.None -> {
        result.pointed.payload_type = MLN_RUNTIME_EVENT_PAYLOAD_NONE
      }
      is RuntimeEventPayload.Unknown ->
        throw IllegalArgumentException("unknown native union variants cannot be submitted")
    }
    return result
  }

  fun readRuntimeEvent(source: mln_runtime_event, message: String = ""): RuntimeEvent =
    RuntimeEvent(
      type = RuntimeEventType(source.type),
      sourceType = RuntimeEventSourceType(source.source_type),
      source = source.source,
      code = source.code,
      payload =
        when (source.payload_type) {
          MLN_RUNTIME_EVENT_PAYLOAD_RENDER_FRAME ->
            RuntimeEventPayload.RenderFrame(
              GeneratedValues.readRuntimeEventRenderFrame(source.payload.render_frame)
            )
          MLN_RUNTIME_EVENT_PAYLOAD_RENDER_MAP ->
            RuntimeEventPayload.RenderMap(
              GeneratedValues.readRuntimeEventRenderMap(source.payload.render_map)
            )
          MLN_RUNTIME_EVENT_PAYLOAD_TILE_ACTION ->
            RuntimeEventPayload.TileAction(
              GeneratedValues.readRuntimeEventTileAction(source.payload.tile_action)
            )
          MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_STATUS ->
            RuntimeEventPayload.OfflineRegionStatus(
              GeneratedValues.readRuntimeEventOfflineRegionStatus(
                source.payload.offline_region_status
              )
            )
          MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_RESPONSE_ERROR ->
            RuntimeEventPayload.OfflineRegionResponseError(
              GeneratedValues.readRuntimeEventOfflineRegionResponseError(
                source.payload.offline_region_response_error
              )
            )
          MLN_RUNTIME_EVENT_PAYLOAD_OFFLINE_REGION_TILE_COUNT_LIMIT ->
            RuntimeEventPayload.OfflineRegionTileCountLimit(
              GeneratedValues.readRuntimeEventOfflineRegionTileCountLimit(
                source.payload.offline_region_tile_count_limit
              )
            )
          MLN_RUNTIME_EVENT_PAYLOAD_CAMERA_TRANSITION_FINISHED ->
            RuntimeEventPayload.CameraTransitionFinished(
              GeneratedValues.readRuntimeEventCameraTransitionFinished(
                source.payload.camera_transition_finished
              )
            )
          MLN_RUNTIME_EVENT_PAYLOAD_NONE -> RuntimeEventPayload.None
          else ->
            RuntimeEventPayload.Unknown(
              source.payload_type.toUInt(),
              GeneratedValues.readUnionBytes(source.payload),
            )
        },
      message = message,
    )

  fun writeRuntimeEventBatchView(
    arena: MemScope,
    value: RuntimeEventBatchView,
  ): CPointer<mln_runtime_event_batch_view> {
    val result = arena.alloc<mln_runtime_event_batch_view>().ptr
    result.reinterpret<ByteVar>().let { bytes ->
      repeat(sizeOf<mln_runtime_event_batch_view>().toInt()) { bytes[it] = 0 }
    }
    result.pointed.size = sizeOf<mln_runtime_event_batch_view>().toUInt()
    result.pointed.events = GeneratedValues.writeRuntimeEventArray(arena, value.events)
    result.pointed.event_count = (value.events.size.toULong()).convert()
    return result
  }

  fun readRuntimeEventBatchView(source: mln_runtime_event_batch_view): RuntimeEventBatchView =
    RuntimeEventBatchView(
      events =
        run {
          val count = (source.event_count).toLong()
          val stride = (source.event_size).toLong()
          require(count in 0..Int.MAX_VALUE.toLong())
          require(stride >= sizeOf<mln_runtime_event>())
          val dataSize = (source.messages_size).toLong()
          List(count.toInt()) { index ->
            val item =
              (source.events!!.reinterpret<ByteVar>() + index.toLong() * stride)!!
                .reinterpret<mln_runtime_event>()
                .pointed
            val offset = (item.message_offset).toLong()
            val length = (item.message_size).toLong()
            require(offset >= 0 && length >= 0 && offset <= dataSize && length <= dataSize - offset)
            GeneratedValues.readRuntimeEvent(
              item,
              GeneratedValues.readRawBytes(
                  (source.messages?.reinterpret<ByteVar>()?.plus(offset)),
                  length.toULong(),
                )
                .decodeToString(),
            )
          }
        }
    )

