  fun writeOfflineRegionDefinition(
    arena: MemScope,
    value: OfflineRegionDefinition,
  ): CPointer<mln_offline_region_definition> {
    val result = arena.alloc<mln_offline_region_definition>().ptr
    result.reinterpret<ByteVar>().let { bytes ->
      repeat(sizeOf<mln_offline_region_definition>().toInt()) { bytes[it] = 0 }
    }
    result.pointed.size = sizeOf<mln_offline_region_definition>().toUInt()
    when (val variant = value.data) {
      is OfflineRegionDefinitionData.TilePyramid -> {
        result.pointed.type = MLN_OFFLINE_REGION_DEFINITION_TILE_PYRAMID
        GeneratedValues.writeOfflineTilePyramidRegionDefinition(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.data.tile_pyramid.ptr)
      }
      is OfflineRegionDefinitionData.Geometry -> {
        result.pointed.type = MLN_OFFLINE_REGION_DEFINITION_GEOMETRY
        GeneratedValues.writeOfflineGeometryRegionDefinition(arena, variant.value)
          .pointed
          .readValue()
          .place(result.pointed.data.geometry.ptr)
      }
      is OfflineRegionDefinitionData.Unknown ->
        throw IllegalArgumentException("unknown native union variants cannot be submitted")
    }
    return result
  }

  fun readOfflineRegionDefinition(source: mln_offline_region_definition): OfflineRegionDefinition =
    OfflineRegionDefinition(
      data =
        when (source.type) {
          MLN_OFFLINE_REGION_DEFINITION_TILE_PYRAMID ->
            OfflineRegionDefinitionData.TilePyramid(
              GeneratedValues.readOfflineTilePyramidRegionDefinition(source.data.tile_pyramid)
            )
          MLN_OFFLINE_REGION_DEFINITION_GEOMETRY ->
            OfflineRegionDefinitionData.Geometry(
              GeneratedValues.readOfflineGeometryRegionDefinition(source.data.geometry)
            )
          else ->
            OfflineRegionDefinitionData.Unknown(
              source.type.toUInt(),
              GeneratedValues.readUnionBytes(source.data),
            )
        }
    )

