  ): CPointer<mln_resource_request> {
    val result = arena.alloc<mln_resource_request>().ptr
    result.reinterpret<ByteVar>().let { bytes ->
      repeat(sizeOf<mln_resource_request>().toInt()) { bytes[it] = 0 }
    }
    result.pointed.size = sizeOf<mln_resource_request>().toUInt()
    result.pointed.has_range = false
    result.pointed.has_prior_modified = false
    result.pointed.has_prior_expires = false
    result.pointed.requested_url =
      if (value.requestedUrl == null) null else GeneratedValues.cString(arena, value.requestedUrl!!)
    result.pointed.resolved_url =
      if (value.resolvedUrl == null) null else GeneratedValues.cString(arena, value.resolvedUrl!!)
    result.pointed.kind = value.kind.rawValue
    result.pointed.loading_method = value.loadingMethod.rawValue
    result.pointed.priority = value.priority.rawValue
    result.pointed.usage = value.usage.rawValue
    result.pointed.storage_policy = value.storagePolicy.rawValue
    if (value.range != null) {
      result.pointed.has_range = true
      result.pointed.range_start = value.range!!.rangeStart
      result.pointed.range_end = value.range!!.rangeEnd
    }
    if (value.priorModifiedUnixMs != null) {
      result.pointed.has_prior_modified = true
      result.pointed.prior_modified_unix_ms = value.priorModifiedUnixMs!!
    }
    if (value.priorExpiresUnixMs != null) {
      result.pointed.has_prior_expires = true
      result.pointed.prior_expires_unix_ms = value.priorExpiresUnixMs!!
    }
    result.pointed.prior_etag =
      if (value.priorEtag == null) null else GeneratedValues.cString(arena, value.priorEtag!!)
    result.pointed.prior_data = GeneratedValues.rawBytes(arena, value.priorData).reinterpret()
    result.pointed.prior_data_size = (value.priorData.size.toULong()).convert()
    return result
  }

